// Formatea RUT chileno de forma tolerante: acepta puntos/guion,
// conserva textos no numéricos y evita romper los campos mientras se escribe.
function formatRut(value){
  const raw=String(value??'').trim();
  if(!raw)return '';
  const compact=raw.replace(/[^0-9kK]/g,'').toUpperCase();
  if(!/^\d{7,8}[0-9K]$/.test(compact)) return raw;
  const body=compact.slice(0,-1), dv=compact.slice(-1);
  return body.replace(/\B(?=(\d{3})+(?!\d))/g,'.')+'-'+dv;
}
window.formatRut=formatRut;

function loadClientContacts(){try{return JSON.parse(localStorage.getItem(CONTACTS_DB)||'{}')||{}}catch{return {}}}
