function clientDestinations(c){const m=clientContact(c);const vals=[...(Array.isArray(c?.destinos)?c.destinos:[]),m.direccion,[m.comuna,m.region].filter(Boolean).join(', ')].filter(Boolean).map(x=>String(x).trim()).filter(Boolean);return [...new Map(vals.map(v=>[normalizeName(v),v])).values()]}
function destinationFromClient(c){return clientDestinations(c)[0]||''}

