function table(headers,rows){const body=rows.map(r=>`<tr>${headers.map(h=>`<td>${esc(r[h])}</td>`).join('')}</tr>`).join('');return `<div class="tableWrap"><table class="table"><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${body||`<tr><td colspan="${headers.length}">Sin registros</td></tr>`}</tbody></table></div>`}
function csvCell(v){return `"${String(v??'').replace(/"/g,'""').replace(/\r?\n/g,' ')}"`}function downloadCsv(filename,columns,rows){if(!rows.length){alert('No hay datos para exportar.');return}const header=columns.map(c=>csvCell(c.label)).join(';');const lines=rows.map(r=>columns.map(c=>csvCell(typeof c.format==='function'?c.format(r[c.key],r):r[c.key])).join(';'));const csv=['sep=;',header,...lines].join('\r\n');const blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500)}
window.openClient=key=>{const c=(state.snapshot?.clients||[]).find(x=>x.key===key);if(!c)return;$('pageTitle').textContent='Ficha de cliente';$('nav').querySelectorAll('button').forEach(b=>b.classList.remove('active'));$('content').innerHTML=`<div class="card"><div class="sectionTitle"><h3>👤 ${esc(c.nombre)}</h3><button class="secondary" type="button" onclick="show('clients')">← Volver</button></div><div class="infoGrid"><div class="info"><small>RUT</small><b>${esc(formatRut(c.rut||'No informado'))}</b></div><div class="info"><small>Documentos</small><b>${c.documentos.length.toLocaleString('es-CL')}</b></div><div class="info"><small>Neto acumulado</small><b>$ ${money(c.neto)}</b></div><div class="info"><small>IVA acumulado</small><b>$ ${money(c.iva)}</b></div><div class="info"><small>Total acumulado</small><b>$ ${money(c.total)}</b></div><div class="info"><small>Fuentes</small><b>${esc([...new Set(c.documentos.map(d=>d.fuente))].join(', ')||'—')}</b></div></div></div><div class="card" style="margin-top:14px"><h3>Documentos asociados</h3>${table(['fuente','fecha','folio','tipo','neto','iva','total'],c.documentos.slice(0,500).map(d=>({fuente:d.fuente,fecha:safeDate(d.fecha),folio:d.folio,tipo:d.tipo,neto:'$ '+money(d.neto),iva:'$ '+money(d.iva),total:'$ '+money(d.total)})))}<p class="note">Mostrando hasta 500 documentos asociados.</p></div>`}
