function renderDashboard(){const m=state.snapshot?.metrics||emptySnap().metrics;const ine=m.ine,s=m.sacos,g=m.granel;$('content').innerHTML=`<div class="hero"><div><small>MOLINO CONTROL</small><h1>Centro de control</h1><p>${hasData()?`Maestro cargado: ${esc(state.snapshot.fileName)}`:'Carga el Excel Maestro para comenzar.'}</p></div><div class="heroIcon">🏭</div></div><div class="grid"><div class="card metric"><small>VENTA NETA INE</small><strong>$ ${money(ine.totalNeto)}</strong></div><div class="card metric"><small>KG INE</small><strong>${money(ine.totalKg)}</strong></div><div class="card metric"><small>PROMEDIO INE</small><strong>$ ${dec(ine.totalPromedio)}/kg</strong></div><div class="card metric"><small>KG HARINAS</small><strong>${money(ine.kgHarinas)}</strong></div><div class="card metric"><small>VENTAS * SACOS</small><strong>${money(s.ventasSacos)}</strong></div><div class="card metric"><small>KG SACOS</small><strong>${money(s.kgSacos)}</strong></div><div class="card metric"><small>KG GRANEL</small><strong>${money(g.totalGranel)}</strong></div><div class="card metric"><small>CLIENTES</small><strong>${(state.snapshot?.clients||[]).length.toLocaleString('es-CL')}</strong></div><div class="card metric"><small>FACTURAS</small><strong>${(state.snapshot?.invoices||[]).length.toLocaleString('es-CL')}</strong></div></div><div class="card"><div class="sectionTitle"><h3>Estado del Maestro</h3><span class="note">${hasData()?`Cargado ${esc(new Date(state.snapshot.lastLoaded).toLocaleString('es-CL'))}`:'Sin archivo'}</span></div>${hasData()?`<div class="sheetList">${state.snapshot.sheets.map(x=>`<span class="sheetTag">${esc(x)}</span>`).join('')}</div>`:'<div class="empty">Ve a <b>Maestro Excel</b> y carga el archivo.</div>'}</div>`}
