async function readExistenceBaseRecords(){let db;try{db=await idb();if(!db.objectStoreNames.contains(STORE_EXISTENCE_BASE))return [];const rows=await new Promise((resolve,reject)=>{const tx=db.transaction(STORE_EXISTENCE_BASE,'readonly');const r=tx.objectStore(STORE_EXISTENCE_BASE).getAll();r.onsuccess=()=>resolve(r.result||[]);r.onerror=()=>reject(r.error)});return rows.sort((a,b)=>String(a.key).localeCompare(String(b.key)))}catch(e){console.warn('No fue posible leer la base de existencias',e);return []}finally{try{db?.close()}catch{}}}
async function persistExistenceBaseRecord(base){if(!base?.key)return base;let db;try{db=await idb();if(db.objectStoreNames.contains(STORE_EXISTENCE_BASE)){await new Promise((resolve,reject)=>{const tx=db.transaction(STORE_EXISTENCE_BASE,'readwrite');tx.objectStore(STORE_EXISTENCE_BASE).put(base);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error||new Error('No se pudo guardar la base de existencias'))});}}catch(e){console.warn('No fue posible persistir la base de existencias',e)}finally{try{db?.close()}catch{}}state.existenceBaseRecords=await readExistenceBaseRecords();return base}
async function deleteExistenceBaseRecord(key){if(!key)return;let db;try{db=await idb();if(db.objectStoreNames.contains(STORE_EXISTENCE_BASE)){await new Promise((resolve,reject)=>{const tx=db.transaction(STORE_EXISTENCE_BASE,'readwrite');tx.objectStore(STORE_EXISTENCE_BASE).delete(String(key));tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error||new Error('No se pudo eliminar la base de existencias'))});}}catch(e){console.warn('No fue posible eliminar la base de existencias',e)}finally{try{db?.close()}catch{}}state.existenceBaseRecords=await readExistenceBaseRecords();}
