const WEATHER_LOCATIONS={
  santiago:{name:'Santiago',region:'Región Metropolitana',lat:-33.4489,lon:-70.6693},
  rancagua:{name:'Rancagua',region:"VI Región · O'Higgins",lat:-34.172221,lon:-70.776110}
};
const weatherCache=new Map();
const weatherLabel=code=>{const c=Number(code);if([0].includes(c))return 'Despejado';if([1,2].includes(c))return 'Parcialmente nublado';if([3].includes(c))return 'Nublado';if([45,48].includes(c))return 'Niebla';if([51,53,55,56,57].includes(c))return 'Llovizna';if([61,63,65,66,67].includes(c))return 'Lluvia';if([71,73,75,77].includes(c))return 'Nieve';if([80,81,82].includes(c))return 'Chubascos';if([95,96,99].includes(c))return 'Tormenta';return 'Condiciones variables'};
const weatherIcon=code=>{const c=Number(code);if([0].includes(c))return '☀️';if([1,2].includes(c))return '⛅';if([3].includes(c))return '☁️';if([45,48].includes(c))return '🌫️';if([51,53,55,56,57].includes(c))return '🌦️';if([61,63,65,66,67,80,81,82].includes(c))return '🌧️';if([71,73,75,77].includes(c))return '🌨️';if([95,96,99].includes(c))return '⛈️';return '🌤️'};
function advisoryFromWeather(data, mode='sacos'){
  const h=data?.hourly||{}; const nowIdx=0; const end=Math.min(12,(h.time||[]).length);
  const probs=(h.precipitation_probability||[]).slice(nowIdx,end).map(Number).filter(Number.isFinite);
  const prec=(h.precipitation||[]).slice(nowIdx,end).map(Number).filter(Number.isFinite);
  const gusts=(h.wind_gusts_10m||[]).slice(nowIdx,end).map(Number).filter(Number.isFinite);
  const maxProb=Math.max(0,...probs), totalPrec=prec.reduce((a,b)=>a+b,0), maxGust=Math.max(0,...gusts);
  const codes=(h.weather_code||[]).slice(nowIdx,end).map(Number);
  const thunder=codes.some(c=>[95,96,99].includes(c));
  const severeRain=maxProb>=70 || totalPrec>=4 || thunder;
  const strongWind=maxGust>=45;
  const cautionRain=maxProb>=50 || totalPrec>=2;
  if(mode==='sacos'){
    if(severeRain||strongWind)return {kind:'bad',title:'⚠️ Clima adverso para despacho en sacos',detail:`Pronóstico próximo: lluvia prob. máx. ${Math.round(maxProb)}% · precipitación acumulada ~${totalPrec.toFixed(1)} mm · ráfagas hasta ${Math.round(maxGust)} km/h.`};
    if(cautionRain||maxGust>=35)return {kind:'warn',title:'🟠 Precaución para despacho en sacos',detail:`Hay riesgo meteorológico moderado: lluvia prob. máx. ${Math.round(maxProb)}% · ráfagas hasta ${Math.round(maxGust)} km/h.`};
    return {kind:'ok',title:'✅ Condiciones favorables para despacho en sacos',detail:`Sin señales fuertes de lluvia o viento en las próximas horas. Lluvia prob. máx. ${Math.round(maxProb)}% · ráfagas hasta ${Math.round(maxGust)} km/h.`};
  }
  if(severeRain||strongWind)return {kind:'warn',title:'⚠️ Condiciones que requieren revisión',detail:`Lluvia prob. máx. ${Math.round(maxProb)}% · precipitación ~${totalPrec.toFixed(1)} mm · ráfagas ${Math.round(maxGust)} km/h.`};
  return {kind:'ok',title:'✅ Condiciones sin alerta fuerte',detail:`Lluvia prob. máx. ${Math.round(maxProb)}% · ráfagas ${Math.round(maxGust)} km/h.`};
}
function advisoryForDate(data,dateStr,mode='sacos'){
  const h=data?.hourly||{}; const target=String(dateStr||'');
  const idxs=(h.time||[]).map((t,i)=>String(t).startsWith(target)?i:-1).filter(i=>i>=0);
  if(!idxs.length){
    const d=data?.daily||{}; const i=(d.time||[]).findIndex(t=>String(t)===target);
    if(i>=0){
      const maxProb=Number(d.precipitation_probability_max?.[i]||0), totalPrec=Number(d.precipitation_sum?.[i]||0), maxGust=Number(d.wind_gusts_10m_max?.[i]||0), code=Number(d.weather_code?.[i]||0);
      const thunder=[95,96,99].includes(code), severeRain=maxProb>=70||totalPrec>=4||thunder, strongWind=maxGust>=45, cautionRain=maxProb>=50||totalPrec>=2;
      if(mode==='sacos'){
        if(severeRain||strongWind)return {kind:'bad',title:'⚠️ Clima adverso para despacho en sacos',detail:`Para ${target}: lluvia prob. máx. ${Math.round(maxProb)}% · precipitación ${totalPrec.toFixed(1)} mm · ráfagas hasta ${Math.round(maxGust)} km/h.`};
        if(cautionRain||maxGust>=35)return {kind:'warn',title:'🟠 Precaución para despacho en sacos',detail:`Para ${target}: lluvia prob. máx. ${Math.round(maxProb)}% · ráfagas hasta ${Math.round(maxGust)} km/h.`};
        return {kind:'ok',title:'✅ Condiciones favorables para despacho en sacos',detail:`Para ${target}: no se detectan señales fuertes de lluvia o viento.`};
      }
    }
    return {kind:'warn',title:'ℹ️ Pronóstico limitado',detail:'La fecha seleccionada está fuera del horizonte disponible del pronóstico.'};
  }
  const slice={hourly:{precipitation_probability:idxs.map(i=>h.precipitation_probability?.[i]),precipitation:idxs.map(i=>h.precipitation?.[i]),wind_gusts_10m:idxs.map(i=>h.wind_gusts_10m?.[i]),weather_code:idxs.map(i=>h.weather_code?.[i])}};
  return advisoryFromWeather(slice,mode);
}
async function fetchWeatherLocation(loc){
  const key=loc.lat+','+loc.lon; const cached=weatherCache.get(key); if(cached && Date.now()-cached.ts<10*60*1000)return cached.data;
  const params=new URLSearchParams({latitude:String(loc.lat),longitude:String(loc.lon),timezone:'America/Santiago',forecast_days:'7',current:'temperature_2m,relative_humidity_2m,precipitation,rain,wind_speed_10m,wind_gusts_10m,weather_code',hourly:'temperature_2m,precipitation_probability,precipitation,wind_gusts_10m,weather_code',daily:'weather_code,temperature_2m_max,temperature_2m_min,precipitation_sum,precipitation_probability_max,wind_gusts_10m_max'});
  const res=await fetch('https://api.open-meteo.com/v1/forecast?'+params.toString(),{cache:'no-store'}); if(!res.ok)throw new Error(`No se pudo consultar el clima (${res.status}).`); const data=await res.json(); weatherCache.set(key,{ts:Date.now(),data}); return data;
}
async function geocodeDestination(q){const name=String(q||'').trim();if(name.length<3)throw new Error('Escribe una comuna o destino más específico.');const u='https://geocoding-api.open-meteo.com/v1/search?'+new URLSearchParams({name,count:'1',language:'es',format:'json'}).toString();const r=await fetch(u,{cache:'no-store'});if(!r.ok)throw new Error('No se pudo localizar el destino.');const j=await r.json();const x=j.results?.[0];if(!x)throw new Error('No encontré ese destino.');return {name:x.name,region:x.admin1||'',lat:x.latitude,lon:x.longitude};}
function weatherCardHtml(title,loc,data){const c=data.current||{};const d=data.daily||{};const days=(d.time||[]).slice(0,7).map((t,i)=>`<div class="weatherDay"><small>${new Date(t+'T12:00:00').toLocaleDateString('es-CL',{weekday:'short'})}</small><b>${weatherIcon(d.weather_code?.[i])}</b><span>${Math.round(Number(d.temperature_2m_max?.[i]||0))}° / ${Math.round(Number(d.temperature_2m_min?.[i]||0))}°</span><div class="weatherSmall">${Math.round(Number(d.precipitation_probability_max?.[i]||0))}% lluvia</div></div>`).join('');const a=advisoryFromWeather(data,'sacos');return `<div class="weatherCard"><div class="weatherHead"><div><h3 style="margin:0">${weatherIcon(c.weather_code)} ${esc(title)}</h3><div class="weatherMeta">${esc(loc.region||'')} · actualizado ${new Date().toLocaleTimeString('es-CL',{hour:'2-digit',minute:'2-digit'})}</div></div><div><div class="weatherTemp">${Math.round(Number(c.temperature_2m||0))}°C</div><div class="weatherMeta">${esc(weatherLabel(c.weather_code))}</div></div></div><div class="weatherMeta" style="margin-top:8px">💧 ${Math.round(Number(c.relative_humidity_2m||0))}% · 💨 ${Math.round(Number(c.wind_speed_10m||0))} km/h · ráfagas ${Math.round(Number(c.wind_gusts_10m||0))} km/h · lluvia ${Number(c.precipitation||0).toFixed(1)} mm</div><div class="weatherForecast">${days}</div><div class="weatherAlert ${a.kind}">${a.title}<div class="weatherSmall" style="margin-top:4px">${a.detail}</div></div></div>`;}
async function renderWeather(){
  $('content').innerHTML=`<div class="card"><div class="sectionTitle"><div><h3>🌦️ Clima operativo</h3><div class="note">Pronóstico actualizado automáticamente. Santiago y Rancagua como referencias; el despacho puede consultar su destino exacto.</div></div><button class="secondary" type="button" id="refreshWeather">↻ Actualizar ahora</button></div><div id="weatherStatus">${status('Consultando pronósticos actuales…','info')}</div><div id="weatherGrid" class="weatherGrid"></div></div><div class="card" style="margin-top:14px"><h3>🚚 Evaluar clima para un despacho</h3><div class="toolbar"><input id="weatherDest" class="grow" placeholder="Escribe comuna o destino, por ejemplo Rancagua, San Fernando, Santiago"><button class="primary" type="button" id="checkDestinationWeather">Evaluar</button></div><div id="destWeather" style="margin-top:12px"></div></div>`;
  async function run(){const box=$('weatherGrid'),st=$('weatherStatus');st.innerHTML=status('Actualizando pronósticos…','info');try{const [s,r]=await Promise.all([fetchWeatherLocation(WEATHER_LOCATIONS.santiago),fetchWeatherLocation(WEATHER_LOCATIONS.rancagua)]);box.innerHTML=weatherCardHtml('Santiago',WEATHER_LOCATIONS.santiago,s)+weatherCardHtml("VI Región · O'Higgins (Rancagua)",WEATHER_LOCATIONS.rancagua,r);st.innerHTML=status('✅ Pronósticos actualizados.','ok')}catch(e){st.innerHTML=status(esc(e.message||String(e)),'err')}}
  $('refreshWeather').onclick=run; $('checkDestinationWeather').onclick=async()=>{const q=$('weatherDest').value.trim();const target=$('destWeather');target.innerHTML=status('Buscando destino y consultando pronóstico…','info');try{const loc=await geocodeDestination(q);const data=await fetchWeatherLocation(loc);const a=advisoryFromWeather(data,'sacos');target.innerHTML=`<div class="weatherCard"><div class="weatherHead"><div><h3>${weatherIcon(data.current?.weather_code)} ${esc(loc.name)}</h3><div class="weatherMeta">${esc(loc.region||'')} · ${Math.round(Number(data.current?.temperature_2m||0))}°C · ${esc(weatherLabel(data.current?.weather_code))}</div></div></div><div class="weatherMeta" style="margin-top:7px">💨 ${Math.round(Number(data.current?.wind_speed_10m||0))} km/h · ráfagas ${Math.round(Number(data.current?.wind_gusts_10m||0))} km/h · humedad ${Math.round(Number(data.current?.relative_humidity_2m||0))}%</div><div class="weatherAlert ${a.kind}" style="margin-top:10px">${a.title}<div class="weatherSmall" style="margin-top:4px">${a.detail}</div></div></div>`}catch(e){target.innerHTML=status(esc(e.message||String(e)),'err')}}; run();}
