function dispatchFormatWeight(formato){const f=String(formato||'').toUpperCase();if(/SACOS\s*25\s*KG|25\s*KG/.test(f))return 25;if(/SACOS\s*10\s*KG|10\s*KG/.test(f))return 10;return 0}
function normalizeDispatchItem(item){const x={...item};const w=dispatchFormatWeight(x.formato);if(w>0&&n(x.cantidad)>0)x.kg=n(x.cantidad)*w;return x}
function updateDispatchKgFromQty(){const fmt=$('dFormat')?.value||'',qty=n($('dQty')?.value||0),kg=$('dKg');if(!kg)return;const w=dispatchFormatWeight(fmt);if(w>0){kg.value=qty>0?String(qty*w):'';kg.readOnly=true;kg.title=`Calculado automáticamente: ${w} kg por saco.`}else{kg.readOnly=false;kg.title='Para Granel O/C ingresa los kilogramos.'}}
function dispatchPlans(){try{const rows=JSON.parse(localStorage.getItem('molino_dispatch_plan_v1')||'[]');return Array.isArray(rows)?rows.map(r=>normalizeDispatchItem({...r,oc:String(r?.oc||'O/C PENDIENTE').trim()||'O/C PENDIENTE'})):[]}catch{return[]}}
function saveDispatchPlans(){try{localStorage.setItem('molino_dispatch_plan_v1',JSON.stringify(state.dispatchPlan))}catch(e){console.warn(e)}}
function defaultProducts(){return ['HARINA GRANEL','HARINA 25 KG','HARINA 10 KG','HARINILLA','GRITZ SEMOL','H.F. MAIZ','ZOOTECNICA','GERMEN','SEMOLINA','GRITZ MEDI','SALVADO','OSN']}
function productOptions(){return [...new Set([...(state.snapshot?.products||[]),...defaultProducts()])].sort((a,b)=>a.localeCompare(b,'es'))}
function renderDraftItems(){const box=$('draftItems');if(!box)return;box.innerHTML=state.dispatchDraftItems.map((it,i)=>`<tr><td>${esc(it.producto)}</td><td>${esc(it.formato)}</td><td>${money(it.cantidad)}</td><td>${money(it.kg)}</td><td>${esc(it.observacion||'')}</td><td><button class="danger smallBtn" type="button" onclick="removeDraftItem(${i})">Quitar</button></td></tr>`).join('')||'<tr><td colspan="6">Aún no has agregado productos.</td></tr>'}
window.removeDraftItem=i=>{state.dispatchDraftItems.splice(i,1);renderDraftItems()}
window.addDraftItem=()=>{const producto=$('dProduct').value.trim(),formato=$('dFormat').value,cantidad=n($('dQty').value),kg=n($('dKg').value),observacion=$('dObs').value.trim();if(!producto){toast('⚠️ Selecciona o escribe un producto.','warn');$('dProduct').focus();return false}if(!cantidad&&!kg){toast('⚠️ Ingresa cantidad o KG.','warn');$('dQty').focus();return false}const autoKg=dispatchFormatWeight(formato);const finalKg=autoKg&&cantidad?cantidad*autoKg:kg;state.dispatchDraftItems.push({producto,formato,cantidad,kg:finalKg,observacion});$('dProduct').value='';$('dQty').value='';$('dKg').value='';$('dObs').value='';renderDraftItems();toast('➕ Producto agregado al despacho.','ok');return true}
window.saveDispatch=()=>{let client=(state.snapshot?.clients||[]).find(c=>c.key===($('dClientKey')?.value||''))||null;const rutInput=$('dRut').value.trim();if(!client&&rutInput)client=findClientByRut(rutInput);const rut=client?.rut||rutInput;const fecha=$('dDate').value,destination=$('dDestination').value.trim(),observacion=($('dGeneralObs')?.value||'').trim(),folio=$('dFolio').value.trim(),oc=(($('dOC')?.value||'').trim()||'O/C PENDIENTE');if(!client&&!rut){toast('⚠️ Selecciona un cliente o ingresa un RUT.','warn');$('dClientSearch').focus();return}if(!fecha){toast('⚠️ Selecciona la fecha de despacho.','warn');$('dDate').focus();return}if(!destination){toast('⚠️ El cliente no tiene una dirección registrada. Completa su ficha de contacto.','warn');$('dDestination').focus();return}if(!state.dispatchDraftItems.length){const producto=$('dProduct').value.trim(),formato=$('dFormat').value,cantidad=n($('dQty').value),kg=n($('dKg').value),observacionItem=$('dObs').value.trim();if(producto&&(cantidad||kg)){state.dispatchDraftItems.push({producto,formato,cantidad,kg:dispatchFormatWeight(formato)&&cantidad?cantidad*dispatchFormatWeight(formato):kg,observacion:observacionItem})}else{toast('⚠️ Agrega un producto con cantidad o KG.','warn');$('dProduct').focus();return}}for(const item of state.dispatchDraftItems){state.dispatchPlan.push(normalizeDispatchItem({id:Date.now()+'-'+Math.random().toString(36).slice(2),fecha,zone:'',cliente:client?.nombre||'',rut:formatRut(rut),destination,folio,oc,producto:item.producto,formato:item.formato,cantidad:item.cantidad,kg:item.kg,observacion:item.observacion||observacion}))}saveDispatchPlans();state.dispatchDraftItems=[];renderDispatches();toast('✅ Despacho guardado en la planilla.','ok')}
window.clearDispatchForm=()=>{state.dispatchDraftItems=[];renderDispatches()}
window.removeDispatch=i=>{state.dispatchPlan.splice(i,1);saveDispatchPlans();renderDispatches()}
function getDispatchPrintRows(){
 const saved=Array.isArray(state.dispatchPlan)?state.dispatchPlan.slice():dispatchPlans();
 const draft=Array.isArray(state.dispatchDraftItems)?state.dispatchDraftItems:[];
 if(!draft.length)return saved;
 const clientKey=$('dClientKey')?.value||'';
 const client=(state.snapshot?.clients||[]).find(c=>c.key===clientKey)||null;
 const rutInput=$('dRut')?.value?.trim()||'';
 const rut=client?.rut||rutInput;
 const fecha=$('dDate')?.value||'';
 const destination=$('dDestination')?.value?.trim()||'';
 const folio=$('dFolio')?.value?.trim()||'';
 const oc=(($('dOC')?.value||'').trim()||'O/C PENDIENTE');
 const obs=$('dObs')?.value?.trim()||'';
 const draftRows=draft.map(item=>({fecha,cliente:client?.nombre||'',rut:formatRut(rut),destination,folio,oc,producto:item.producto,formato:item.formato,cantidad:item.cantidad,kg:item.kg,observacion:item.observacion||obs}));
 return saved.concat(draftRows);
}
