function safeOpenPrintWindow(html){const w=window.open('', '_blank', 'noopener,noreferrer,width=1200,height=850');if(!w)return null;try{w.document.open();w.document.write(html);w.document.close();return w}catch(e){try{w.close()}catch{};return null}}
function makePrintHtml(rows,from,to,logo){
 const weekLabel=`Semana ${from||'____/__/__'} — ${to||'____/__/__'}`;
 const tr=rows.map((r,i)=>`<tr><td>${i+1}</td><td>${esc(r.cliente)}</td><td>${esc(r.rut)}</td><td>${esc(r.destination)}</td><td>${esc(r.producto)}</td><td>${esc(r.formato)}</td><td class=\"num\">${esc(money(r.cantidad))}</td><td class=\"num\">${esc(money(r.kg))}</td><td>${esc(r.fecha)}</td><td>${esc(r.oc||'O/C PENDIENTE')}</td><td>${esc(r.observacion||'')}</td></tr>`).join('');
 const totalKg=rows.reduce((s,r)=>s+n(r.kg),0), totalQty=rows.reduce((s,r)=>s+n(r.cantidad),0);
 const logoHtml=logo?`<img src=\"${logo}\" alt=\"Molinos San Miguel\" class=\"printLogo\">`:`<div class=\"logoFallback\">MOLINOS<br>SAN MIGUEL</div>`;
 return `<!doctype html><html lang=\"es\"><head><meta charset=\"utf-8\"><title>Planilla de Despachos - Molino Control</title><style>@page{size:A4 landscape;margin:8mm}html,body{margin:0;padding:0;background:#fff;color:#111;font-family:Arial,Helvetica,sans-serif}body{font-size:10px}.sheet{width:100%}.header{display:grid;grid-template-columns:90px 1fr 170px;align-items:center;border-bottom:2px solid #123a78;padding-bottom:8px;margin-bottom:8px}.printLogo{width:72px;height:55px;object-fit:contain}.title{text-align:center;font-size:18px;font-weight:800;color:#123a78}.sub{text-align:center;font-size:11px;margin-top:3px}.meta{text-align:right;font-size:9px}.table{width:100%;border-collapse:collapse;table-layout:fixed}.table th,.table td{border:1px solid #4b5563;padding:4px 5px;vertical-align:middle;word-break:break-word}.table th{background:#e8eef7;color:#123a78;font-weight:800;text-align:center}.num{text-align:right}.empty{text-align:center;padding:20px}.totals{display:flex;justify-content:flex-end;gap:18px;font-weight:800;margin-top:8px}.footer{margin-top:12px;border-top:1px solid #94a3b8;padding-top:6px;display:flex;justify-content:space-between}.sign{margin-top:18px;display:grid;grid-template-columns:1fr 1fr;gap:80px}.line{border-top:1px solid #111;text-align:center;padding-top:4px}thead{display:table-header-group}tr{page-break-inside:avoid}button{display:none}@media print{body{-webkit-print-color-adjust:exact;print-color-adjust:exact}}</style></head><body><div class=\"sheet\"><div class=\"header\">${logoHtml}<div><div class=\"title\">REPARTOS / PLANILLA DE DESPACHOS</div><div class=\"sub\">MOLINOS SAN MIGUEL LTDA · ${esc(weekLabel)}</div></div><div class=\"meta\">Fecha impresión: ${new Date().toLocaleDateString('es-CL')}<br>Registros: ${rows.length}</div></div><table class=\"table\"><thead><tr><th>#</th><th>Cliente</th><th>RUT</th><th>Destino</th><th>Producto</th><th>Formato</th><th>Cant.</th><th>KG</th><th>Fecha</th><th>O/C</th><th>Observación</th></tr></thead><tbody>${tr||'<tr><td colspan=\"11\" class=\"empty\">Sin despachos registrados.</td></tr>'}</tbody></table><div class=\"totals\"><span>Total registros: ${rows.length}</span><span>Total KG: ${money(totalKg)}</span><span>Total unidades: ${money(totalQty)}</span></div><div class=\"footer\"><div>Planilla generada desde Molino Control.</div><div>Hoja semanal de repartos</div></div><div class=\"sign\"><div class=\"line\">Preparado / Programado</div><div class=\"line\">Revisado / Despachado</div></div></div></body></html>`
}
function buildPrintPlan(){
 const from=$('weekFrom')?.value||'',to=$('weekTo')?.value||'',rows=getDispatchPrintRows();
 $('printArea').innerHTML='<div style="padding:20px;font-family:Arial">Vista de impresión preparada. Usa el botón Imprimir para abrir la planilla A4.</div>';
 return {from,to,rows}
}
window.printDispatchPlan=()=>{
 const {from,to,rows}=buildPrintPlan();
 const html=makePrintHtml(rows,from,to,EMBEDDED_LOGO_DATA);
 const w=safeOpenPrintWindow(html);
 if(w){
   w.onload=()=>{setTimeout(()=>{try{w.focus();w.print()}catch{}},120)};
   setTimeout(()=>{try{w.focus();w.print()}catch{}},650);
   return;
 }
 // Fallback: print from the current page with a dedicated print-only container.
 const host=$('printArea');
 if(!host){alert('No se pudo preparar la impresión.');return}
 const previous=document.body.innerHTML;
 document.body.innerHTML=html.replace(/^<!doctype html><html[^>]*><head>/i,'<head>').replace(/<\/head>.*?<body[^>]*>/is,'').replace(/<\/body>.*?<\/html>/is,'');
 try{window.print()}finally{location.reload()}
}
window.downloadDispatchPlanHtml=()=>{
 const {from,to,rows}=buildPrintPlan();
 const html=makePrintHtml(rows,from,to,EMBEDDED_LOGO_DATA);
 const a=document.createElement('a');
 const url=URL.createObjectURL(new Blob([html],{type:'text/html;charset=utf-8'}));
 a.href=url; a.download='planilla_despachos_molino_control.html';
 document.body.appendChild(a); a.click(); a.remove();
 setTimeout(()=>URL.revokeObjectURL(url),1500);
}
function selectDispatchClient(c){if(!c)return;$('dClientSearch').value=c.nombre||'';$('dClientKey').value=c.key||'';$('dRut').value=formatRut(c.rut||'');const dests=clientDestinations(c);const list=$('destinationList');if(list)list.innerHTML=dests.map(v=>`<option value="${esc(v)}"></option>`).join('');const dest=dests[0]||'';$('dDestination').value=dest;$('dDestination').placeholder=dests.length?`Destino registrado · ${dests.length} opción${dests.length===1?'':'es'}`:'Destino no registrado — completa la ficha del cliente';$('clientSuggestions')?.classList.add('hidden')}
function setupDispatchClientAutocomplete(clients){const input=$('dClientSearch'),box=$('clientSuggestions'),rutInput=$('dRut');if(!input||!box)return;let timer;const paint=(q)=>{const v=String(q||'').trim().toLowerCase();if(!v){box.classList.add('hidden');return}const qn=normalize(v);const rows=clients.filter(c=>String(c.nombre||'').toLowerCase().includes(v)||normalize(c.rut||'').includes(qn)).slice(0,12);box.innerHTML=rows.map(c=>`<div class="suggestion" data-key="${esc(c.key)}"><strong>${esc(c.nombre||'Cliente sin nombre')}</strong><span>${esc(formatRut(c.rut||'RUT no informado'))}</span></div>`).join('');box.classList.toggle('hidden',rows.length===0);box.querySelectorAll('.suggestion').forEach(el=>el.addEventListener('mousedown',e=>{e.preventDefault();selectDispatchClient(clients.find(x=>x.key===el.dataset.key))}))};input.addEventListener('input',()=>{clearTimeout(timer);$('dClientKey').value='';const q=input.value.trim();timer=setTimeout(()=>paint(q),80)});input.addEventListener('focus',()=>paint(input.value));input.addEventListener('blur',()=>setTimeout(()=>box.classList.add('hidden'),250));box.addEventListener('mousedown',e=>e.preventDefault());if(rutInput){const syncRut=()=>{const raw=rutInput.value.trim();if(!raw)return;const c=findClientByRut(raw);if(c)selectDispatchClient(c);else{$('dClientKey').value='';rutInput.value=formatRut(raw)}};rutInput.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(syncRut,220)});rutInput.addEventListener('change',syncRut);rutInput.addEventListener('blur',syncRut)}}
function renderDispatches(){if(!state.dispatchPlan.length)state.dispatchPlan=dispatchPlans();const products=productOptions();const clients=state.snapshot?.clients||[];const m=state.snapshot?.metrics||emptySnap().metrics;const g=m.granel,s=m.sacos;$('content').innerHTML=`<div class="card"><div class="sectionTitle"><h3>🚚 Despachos</h3><div class="toolbar"><span class="pill">${state.dispatchPlan.length} líneas planificadas</span><button class="secondary" type="button" onclick="printDispatchPlan()">🖨️ Imprimir / Guardar PDF</button><button class="secondary" type="button" onclick="downloadDispatchPlanHtml()">⬇️ Descargar planilla</button><a class="secondary" style="text-decoration:none;display:inline-block" href="/planilla_despachos_molino_control.docx" download>📄 Plantilla Word</a></div></div><div class="kpiRow"><div class="kpi"><small>VENTAS * SACOS</small><b>${money(s.ventasSacos)}</b></div><div class="kpi"><small>KG SACOS</small><b>${money(s.kgSacos)}</b></div><div class="kpi"><small>KG GRANEL</small><b>${money(g.totalGranel)}</b></div><div class="kpi"><small>PRODUCTOS DISPONIBLES</small><b>${products.length}</b></div></div></div><div class="card" style="margin-top:14px"><h3>📋 Nueva orden de despacho</h3><p class="note">Escribe el nombre y usa el autocompletado. El clima del destino se puede evaluar antes de enviar sacos.</p><div class="dispatchForm"><div class="autocomplete"><label>Cliente</label><input id="dClientSearch" type="text" autocomplete="off" placeholder="Escribe el nombre del cliente…"><input id="dClientKey" type="hidden"><div id="clientSuggestions" class="suggestions hidden"></div></div><div><label>RUT</label><input id="dRut" type="text" inputmode="numeric" maxlength="15" autocomplete="off" list="rutList" placeholder="Ej. 18.446.726-7"><datalist id="rutList">${clients.slice(0,2000).map(c=>`<option value="${esc(formatRut(c.rut||''))}">${esc(c.nombre||'')}</option>`).join('')}</datalist></div><div><label>Destino registrado / dirección</label><input id="dDestination" list="destinationList" placeholder="Selecciona el destino del cliente"><datalist id="destinationList"></datalist><small class="note">Los destinos registrados en el Excel aparecen automáticamente al seleccionar el cliente.</small><button class="ghost" type="button" id="dWeatherCheck" style="margin-top:7px;width:100%">🌦️ Evaluar clima para sacos</button><div id="dWeatherAdvice" style="margin-top:7px"></div></div><div><label>Fecha despacho</label><input id="dDate" type="date"></div><div><label>Folio / referencia</label><input id="dFolio" placeholder="Opcional"></div><div><label>O/C</label><input id="dOC" type="text" autocomplete="off" placeholder="Ej. O/C 12345" value="O/C PENDIENTE"></div><div class="full"><label>Producto</label><input id="dProduct" list="productList" placeholder="Selecciona o escribe producto"><datalist id="productList">${products.map(p=>`<option value="${esc(p)}"></option>`).join('')}</datalist></div><div><label>Formato</label><select id="dFormat"><option value="Sacos 25 KG">Sacos 25 KG</option><option value="Sacos 10 KG">Sacos 10 KG</option><option value="Granel O/C">Granel O/C</option></select></div><div><label>Cantidad</label><input id="dQty" type="number" min="0" step="1" placeholder="Sacos / unidades"></div><div><label>KG</label><input id="dKg" type="number" min="0" step="1" placeholder="Kilogramos"></div><div><label>Observación del ítem</label><input id="dObs" placeholder="Opcional"></div><div class="full"><div class="toolbar"><button class="secondary" type="button" onclick="addDraftItem()">➕ Agregar producto al despacho</button><button class="primary" type="button" onclick="saveDispatch()">✅ Guardar despacho</button><button class="ghost" type="button" onclick="clearDispatchForm()">Limpiar</button></div></div></div><div class="dispatchItems tableWrap"><div class="note" style="margin-bottom:8px">Puedes agregar varios ítems al mismo pedido: por ejemplo, <b>Sacos 25 KG</b> + <b>Sacos 10 KG</b> + <b>Granel O/C</b>. Todo queda en una sola orden.</div><table class="table"><thead><tr><th>Producto</th><th>Formato</th><th>Cantidad</th><th>KG</th><th>Observación</th><th></th></tr></thead><tbody id="draftItems"></tbody></table></div></div><div class="card" style="margin-top:14px"><div class="sectionTitle"><h3>🗓️ Planilla semanal</h3><div class="toolbar"><label style="margin:0">Desde <input id="weekFrom" type="date"></label><label style="margin:0">Hasta <input id="weekTo" type="date"></label></div></div><div class="toolbar" style="margin:8px 0"><button class="secondary" type="button" onclick="printDispatchPlan()">🖨️ Imprimir</button><button class="secondary" type="button" onclick="downloadDispatchPlanHtml()">⬇️ Descargar</button><a class="secondary" style="text-decoration:none;display:inline-block" href="/planilla_despachos_molino_control.docx" download>📄 Word</a></div>${table(['fecha','cliente','rut','destination','producto','formato','cantidad','kg','folio','oc','observacion'],state.dispatchPlan.map(r=>({fecha:r.fecha,cliente:r.cliente,rut:r.rut,destination:r.destination,producto:r.producto,formato:r.formato,cantidad:money(r.cantidad),kg:money(r.kg),folio:r.folio,oc:r.oc||'O/C PENDIENTE',observacion:r.observacion})))}<div class="note">La planilla de impresión toma estas líneas y las presenta en un formato similar a la hoja semanal de repartos.</div></div>`;
setupDispatchClientAutocomplete(clients);$('dQty').oninput=updateDispatchKgFromQty;$('dFormat').onchange=updateDispatchKgFromQty;updateDispatchKgFromQty();$('dRut').oninput=()=>{const v=$('dRut').value;const c=findClientByRut(v);if(c){selectDispatchClient(c)}else if(!v){$('dClientSearch').value='';$('dClientKey').value=''}};$('dRut').onblur=()=>{$('dRut').value=formatRut($('dRut').value);const c=findClientByRut($('dRut').value);if(c)selectDispatchClient(c)};$('dWeatherCheck').onclick=()=>checkDispatchWeather();$('weekFrom').value=new Date().toISOString().slice(0,10);const d=new Date();d.setDate(d.getDate()+6);$('weekTo').value=d.toISOString().slice(0,10);renderDraftItems()}

